using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using Newtonsoft.Json.Linq;
public static class CheckFloorHeights {public static object Run(){var rows=JArray.Parse(File.ReadAllText(Path.GetFullPath(Path.Combine(Application.dataPath,"../../../SourceAssets/FloorSurfaceWear/B5_renderers.json"))));var r=rows.Single(r=>(string)r["name"]=="CF_B5-T01_Vault.001");var m=AssetDatabase.LoadAllAssetsAtPath((string)r["asset"]).OfType<Mesh>().Single(m=>m.name==(string)r["mesh"]);var v=m.vertices;var ix=m.triangles;var a=new System.Collections.Generic.List<float>();for(int i=0;i<ix.Length;i+=3){var n=Vector3.Cross(v[ix[i+1]]-v[ix[i]],v[ix[i+2]]-v[ix[i]]).normalized;if(n.y>.93f)a.Add((v[ix[i]].y+v[ix[i+1]].y+v[ix[i+2]].y)/3);}return a.GroupBy(y=>Mathf.Round(y*1000)/1000).Select(g=>new{y=g.Key,triangles=g.Count()});}}
